/* From Uiverse.io by andrew-demchenk0 - Tags: switch, dark, light, theme-switch */
.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 64px;
  height: 34px;
}

.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #73C0FC;
  transition: .4s;
  border-radius: 30px;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  height: 30px;
  width: 30px;
  border-radius: 20px;
  left: 2px;
  bottom: 2px;
  z-index: 2;
  background-color: #e8e8e8;
  transition: .4s;
}

.__UIV_SCOPE__ .sun svg {
  position: absolute;
  top: 6px;
  left: 36px;
  z-index: 1;
  width: 24px;
  height: 24px;
}

.__UIV_SCOPE__ .moon svg {
  fill: #73C0FC;
  position: absolute;
  top: 5px;
  left: 5px;
  z-index: 1;
  width: 24px;
  height: 24px;
}

/* .switch:hover */.__UIV_SCOPE__ .sun svg {
  animation: rotate 15s linear infinite;
}

@keyframes rotate {
 
  0% {
    transform: rotate(0);
  }

  100% {
    transform: rotate(360deg);
  }
}

/* .switch:hover */.__UIV_SCOPE__ .moon svg {
  animation: tilt 5s linear infinite;
}

@keyframes tilt {
 
  0% {
    transform: rotate(0deg);
  }

  25% {
    transform: rotate(-10deg);
  }

  75% {
    transform: rotate(10deg);
  }

  100% {
    transform: rotate(0deg);
  }
}

.__UIV_SCOPE__ .input:checked + .slider {
  background-color: #183153;
}

.__UIV_SCOPE__ .input:focus + .slider {
  box-shadow: 0 0 1px #183153;
}

.__UIV_SCOPE__ .input:checked + .slider:before {
  transform: translateX(30px);
}
